-- Row Level Security on every new table (no policies: the app is the owner, as for every other table).
ALTER TABLE "Product"             ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TaxRate"             ENABLE ROW LEVEL SECURITY;
ALTER TABLE "PlanProductDiscount" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "PromotionProduct"    ENABLE ROW LEVEL SECURITY;
ALTER TABLE "OpenCharge"          ENABLE ROW LEVEL SECURITY;
ALTER TABLE "OpenChargeRemoval"   ENABLE ROW LEVEL SECURITY;

-- Charge history is append-only: an open line is never edited or deleted (it is removed by a removal row, or checked out).
CREATE TRIGGER "OpenCharge_no_update_delete"        BEFORE UPDATE OR DELETE ON "OpenCharge"        FOR EACH ROW       EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "OpenCharge_no_truncate"             BEFORE TRUNCATE         ON "OpenCharge"        FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "OpenChargeRemoval_no_update_delete" BEFORE UPDATE OR DELETE ON "OpenChargeRemoval" FOR EACH ROW       EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "OpenChargeRemoval_no_truncate"      BEFORE TRUNCATE         ON "OpenChargeRemoval" FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();

-- Shapes. A rate is in thousandths of a percent (100% = 100000).
ALTER TABLE "Product"             ADD CONSTRAINT "Product_shape"             CHECK ("priceCents" >= 0 AND length(btrim("name")) > 0 AND length(btrim("category")) > 0);
ALTER TABLE "TaxRate"             ADD CONSTRAINT "TaxRate_shape"             CHECK ("rateMilli" BETWEEN 0 AND 100000);
ALTER TABLE "PlanProductDiscount" ADD CONSTRAINT "PlanProductDiscount_shape" CHECK ("percent" BETWEEN 0 AND 100);
-- An open line is a service or a product, never both; a service is never taxed (decision 2).
ALTER TABLE "OpenCharge" ADD CONSTRAINT "OpenCharge_shape" CHECK (
  ("serviceId" IS NULL) <> ("productId" IS NULL)
  AND "unitPriceCents" >= 0 AND "taxRateMilli" BETWEEN 0 AND 100000
  AND ("serviceId" IS NULL OR "taxRateMilli" = 0)
);

-- What a charge is (rev 2.3, A-29), restated. DUES: no visit. A VISIT: its encounter, booking and service. An ADD-ON SERVICE: a service
-- and the open line it came from, no booking. A PRODUCT: a product and its open line, paid in money only — membership credits and
-- perks never pay for a product (decision 3a).
ALTER TABLE "RevenueEvent" DROP CONSTRAINT "RevenueEvent_kind";
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_kind" CHECK (
  ("paymentType" = 'DUES'
     AND "encounterId" IS NULL AND "bookingId" IS NULL AND "serviceId" IS NULL AND "productId" IS NULL AND "openChargeId" IS NULL
     AND "membershipId" IS NOT NULL AND "periodStart" IS NOT NULL AND "billingStatus" IS NOT NULL AND "patientId" IS NOT NULL)
  OR ("paymentType" <> 'DUES'
     AND "membershipId" IS NULL AND "periodStart" IS NULL AND "billingStatus" IS NULL
     AND (
           ("encounterId" IS NOT NULL AND "bookingId" IS NOT NULL AND "serviceId" IS NOT NULL AND "productId" IS NULL AND "openChargeId" IS NULL)
        OR ("encounterId" IS NULL AND "bookingId" IS NULL AND "serviceId" IS NOT NULL AND "productId" IS NULL AND "openChargeId" IS NOT NULL AND "patientId" IS NOT NULL)
        OR ("encounterId" IS NULL AND "bookingId" IS NULL AND "serviceId" IS NULL AND "productId" IS NOT NULL AND "openChargeId" IS NOT NULL AND "patientId" IS NOT NULL
            AND "paymentType" = 'CASH')
     ))
);

-- The money rule, restated (rev 2.3): an adjustment may now be NEGATIVE — a price raised above list, which only an admin may do
-- (decision 5; the app enforces who) — and always has its reason. Sales tax: products only, at the snapshotted rate, on the net, halves up.
ALTER TABLE "RevenueEvent" DROP CONSTRAINT "RevenueEvent_consistent";
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_consistent" CHECK (
  "creditsRedeemed" >= 0 AND "netPriceCents" >= 0 AND "discountCents" >= 0 AND "promotionCents" >= 0
  AND "discountPercent" BETWEEN 0 AND 100
  AND ("listPriceCents" IS NULL OR "listPriceCents" >= 0)
  AND (("promotionCents" > 0) = ("promotionId" IS NOT NULL))
  AND ("promotionCents" = 0 OR "discountCents" = 0)
  AND (("adjustmentCents" <> 0) = ("adjustmentReason" IS NOT NULL))
  AND ("adjustmentReason" IS DISTINCT FROM 'OTHER' OR length(btrim(coalesce("adjustmentNote", ''))) > 0)
  AND "taxRateMilli" BETWEEN 0 AND 100000
  AND ("taxRateMilli" = 0 OR "productId" IS NOT NULL)
  AND "taxCents" = (("netPriceCents"::bigint * "taxRateMilli" + 50000) / 100000)
  AND (("paymentType" = 'CASH'   AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0 AND "listPriceCents" IS NOT NULL
        AND "netPriceCents" = "listPriceCents" - "discountCents" - "promotionCents" - "adjustmentCents"
        AND ("discountPercent" > 0 OR "discountCents" = 0))
    OR ("paymentType" = 'MEMBER' AND "memberBenefit" IS NOT NULL AND "netPriceCents" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0 AND "promotionCents" = 0 AND "adjustmentCents" = 0
        AND ("memberBenefit" = 'CREDITS') = ("creditsRedeemed" > 0))
    OR ("paymentType" = 'DUES' AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0 AND "promotionCents" = 0 AND "adjustmentCents" = 0
        AND "listPriceCents" IS NOT NULL AND "listPriceCents" > 0 AND "netPriceCents" = "listPriceCents"))
);

-- The money guard, restated: a line owes its net PLUS its tax (rev 2.3), so it may be paid up to that and no more. Otherwise unchanged.
CREATE OR REPLACE FUNCTION nw_money_guard() RETURNS trigger AS $$
DECLARE
  p_amount integer; p_patient text; accounted integer;
  c_net integer; c_patient text; c_kind text; c_pre boolean; settled integer;
  credit integer; charge_id text; patient text; matched integer;
BEGIN
  IF TG_TABLE_NAME = 'Payment' THEN
    SELECT COALESCE((SELECT SUM("amountCents") FROM "PaymentAllocation" WHERE "paymentId" = NEW."id"), 0)
         + COALESCE((SELECT SUM("amountCents") FROM "Refund" WHERE "paymentId" = NEW."id" AND "source" = 'OVERPAYMENT'), 0)
         + COALESCE((SELECT SUM("deltaCents") FROM "AccountCreditEntry" WHERE "paymentId" = NEW."id" AND "kind" = 'OVERPAYMENT'), 0)
      INTO accounted;
    IF accounted <> NEW."amountCents" THEN
      RAISE EXCEPTION 'payment % is not fully accounted for (% of %)', NEW."id", accounted, NEW."amountCents" USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'PaymentAllocation' THEN
    SELECT "amountCents", "patientId" INTO p_amount, p_patient FROM "Payment" WHERE "id" = NEW."paymentId";
    IF EXISTS (SELECT 1 FROM "PaymentReversal" WHERE "paymentId" = NEW."paymentId") THEN
      RAISE EXCEPTION 'allocation % is from a reversed payment', NEW."id" USING ERRCODE = 'check_violation';
    END IF;
    charge_id := NEW."revenueEventId"; patient := p_patient;
  ELSIF TG_TABLE_NAME = 'AccountCreditEntry' THEN
    SELECT COALESCE(SUM("deltaCents"), 0) INTO credit FROM "AccountCreditEntry" WHERE "patientId" = NEW."patientId";
    IF credit < 0 THEN
      RAISE EXCEPTION 'account credit of patient % would go below zero', NEW."patientId" USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."kind" <> 'APPLIED' THEN RETURN NULL; END IF;
    charge_id := NEW."revenueEventId"; patient := NEW."patientId";
  ELSIF TG_TABLE_NAME = 'Refund' THEN
    IF NEW."source" = 'ACCOUNT_CREDIT' THEN
      SELECT COALESCE(SUM(-"deltaCents"), 0) INTO matched FROM "AccountCreditEntry" WHERE "refundId" = NEW."id" AND "kind" = 'REFUNDED' AND "patientId" = NEW."patientId";
      IF matched <> NEW."amountCents" THEN
        RAISE EXCEPTION 'account-credit refund % has no matching account credit', NEW."id" USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NOT EXISTS (SELECT 1 FROM "Payment" WHERE "id" = NEW."paymentId" AND "patientId" = NEW."patientId") THEN
        RAISE EXCEPTION 'overpayment refund % is not from this patient''s payment', NEW."id" USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NULL;
  ELSE
    RETURN NULL;
  END IF;

  -- A settlement of one charge (an allocation, or account credit applied): the charge's own rules.
  SELECT "netPriceCents" + "taxCents", "patientId", "paymentType"::text INTO c_net, c_patient, c_kind FROM "RevenueEvent" WHERE "id" = charge_id;
  IF c_kind IS NULL OR c_kind = 'DUES' OR c_patient IS DISTINCT FROM patient THEN
    RAISE EXCEPTION 'charge % cannot be settled from this patient''s money', charge_id USING ERRCODE = 'check_violation';
  END IF;
  SELECT EXISTS (SELECT 1 FROM "PreTrackingSettlement" WHERE "revenueEventId" = charge_id) INTO c_pre;
  IF c_pre THEN
    RAISE EXCEPTION 'charge % was settled before payments were tracked', charge_id USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE((SELECT SUM(a."amountCents") FROM "PaymentAllocation" a
                    WHERE a."revenueEventId" = charge_id
                      AND NOT EXISTS (SELECT 1 FROM "PaymentReversal" r WHERE r."paymentId" = a."paymentId")), 0)
       + COALESCE((SELECT SUM(-e."deltaCents") FROM "AccountCreditEntry" e WHERE e."revenueEventId" = charge_id AND e."kind" = 'APPLIED'), 0)
    INTO settled;
  IF settled > c_net THEN
    RAISE EXCEPTION 'charge % would be paid more than it costs', charge_id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Open lines, checked at COMMIT: a line is checked out at most once (the unique openChargeId) and never after it was removed, nor
-- removed after it was checked out; and the charge carries the line's SNAPSHOTS unchanged — its patient, its service or product, its
-- name, its price and its tax rate (decision 1: a catalog edit never changes a charge).
CREATE OR REPLACE FUNCTION nw_open_charge_guard() RETURNS trigger AS $$
DECLARE
  oc record; oc_id text;
BEGIN
  oc_id := NEW."openChargeId";   -- both tables name the line by this column
  IF oc_id IS NULL THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM "OpenChargeRemoval" WHERE "openChargeId" = oc_id) AND EXISTS (SELECT 1 FROM "RevenueEvent" WHERE "openChargeId" = oc_id) THEN
    RAISE EXCEPTION 'open charge % was both removed and checked out', oc_id USING ERRCODE = 'check_violation';
  END IF;
  IF TG_TABLE_NAME = 'RevenueEvent' THEN
    SELECT * INTO oc FROM "OpenCharge" WHERE "id" = oc_id;
    IF oc."patientId" IS DISTINCT FROM NEW."patientId" OR oc."serviceId" IS DISTINCT FROM NEW."serviceId" OR oc."productId" IS DISTINCT FROM NEW."productId"
       OR oc."name" IS DISTINCT FROM NEW."serviceName" OR oc."unitPriceCents" IS DISTINCT FROM NEW."listPriceCents"
       OR oc."taxRateMilli" IS DISTINCT FROM NEW."taxRateMilli" THEN
      RAISE EXCEPTION 'charge % does not match the open line it was checked out from', NEW."id" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE CONSTRAINT TRIGGER "OpenChargeRemoval_guard"   AFTER INSERT ON "OpenChargeRemoval" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION nw_open_charge_guard();
CREATE CONSTRAINT TRIGGER "RevenueEvent_open_charge_guard" AFTER INSERT ON "RevenueEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
  WHEN (NEW."openChargeId" IS NOT NULL) EXECUTE FUNCTION nw_open_charge_guard();

-- Promotions may now cover products (decision 3c); once a charge has used a promotion, its products are frozen like its services.
CREATE OR REPLACE FUNCTION nw_promotion_guard() RETURNS trigger AS $$
DECLARE
  pid text;
  used boolean;
BEGIN
  -- Separate branches: PL/pgSQL resolves a record's field even in a CASE arm that is not taken.
  IF TG_TABLE_NAME = 'Promotion' THEN pid := OLD."id"; ELSE pid := OLD."promotionId"; END IF;
  IF TG_OP = 'DELETE' AND TG_TABLE_NAME = 'Promotion' THEN
    RAISE EXCEPTION 'a promotion is never deleted (deactivate it)' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT EXISTS (SELECT 1 FROM "RevenueEvent" WHERE "promotionId" = pid) INTO used;
  IF NOT used THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_TABLE_NAME = 'PromotionService' THEN
    RAISE EXCEPTION 'promotion % has been used: its services are frozen', pid USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_TABLE_NAME = 'PromotionProduct' THEN
    RAISE EXCEPTION 'promotion % has been used: its products are frozen', pid USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW."kind" IS DISTINCT FROM OLD."kind" OR NEW."value" IS DISTINCT FROM OLD."value"
     OR NEW."startsOn" IS DISTINCT FROM OLD."startsOn" OR NEW."endsOn" IS DISTINCT FROM OLD."endsOn" THEN
    RAISE EXCEPTION 'promotion % has been used: its kind, value and dates are frozen', pid USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER "PromotionProduct_guard" BEFORE UPDATE OR DELETE ON "PromotionProduct" FOR EACH ROW EXECUTE FUNCTION nw_promotion_guard();
CREATE TRIGGER "PromotionProduct_no_truncate" BEFORE TRUNCATE ON "PromotionProduct" FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();

